def pre(x):
    return And(x >= 0, x <= 9999)

def post(x, r):
    # Candidate results: insert 5 so that t trailing digits of x stay after it.
    # t = 0 inserts at the end, t = d (number of digits) inserts at the front.
    # t = 0 and t = 1 are always valid (x = 0 has one digit).
    # For t >= 2, the insertion is valid only if x has at least t digits.
    options = []      # Or-terms: the value r equals a valid candidate
    bounds = []       # And-terms: r is at least every valid candidate
    for t in range(5):
        c = (x // 10**t) * 10**(t + 1) + 5 * 10**t + x % 10**t
        if t <= 1:
            options.append(And(r == c))
            bounds.append(r >= c)
        else:
            cond = x >= 10**(t - 1)
            options.append(And(cond, r == c))
            bounds.append(Implies(cond, r >= c))
    return And(Or(*options), And(*bounds))
